public class Figura {
    String nombre;
    Figura(String nombre) { this.nombre = nombre; }
    double calcularArea() { return 0; }
    void describir() { System.out.println(nombre + " area: " + calcularArea()); }
}

public class Circulo extends Figura {
    double radio;
    Circulo(double radio) { super("Circulo"); this.radio = radio; }
    @Override
    double calcularArea() { return Math.PI * radio * radio; }
}

public class Rectangulo extends Figura {
    double base, altura;
    Rectangulo(double base, double altura) { super("Rectangulo"); this.base = base; this.altura = altura; }
    @Override
    double calcularArea() { return base * altura; }
}

public class Main {
    public static void main(String[] args) {
        Figura c = new Circulo(5);
        Figura r = new Rectangulo(4, 6);
        c.describir();
        r.describir();
    }
}

