public class Vehiculo {
    String marca;
    int anio;

    Vehiculo(String marca, int anio) {
        this.marca = marca;
        this.anio = anio;
    }

    void mostrarInfo() {
        System.out.println(marca + " | Anio: " + anio);
    }

    String getTipo() {
        return "Vehiculo base";
    }
}

public class Auto extends Vehiculo {
    int puertas;
    String combustible;

    Auto(String marca, int anio, int puertas, String combustible) {
        super(marca, anio);
        this.puertas = puertas;
        this.combustible = combustible;
    }

    @Override
    void mostrarInfo() {
        super.mostrarInfo();
        System.out.println("Puertas: " + puertas + " | Combustible: " + combustible);
    }

    @Override
    String getTipo() { return "Auto"; }
}

public class Camioneta extends Vehiculo {
    double cargaMax;
    String traccion;

    Camioneta(String marca, int anio, double cargaMax, String traccion) {
        super(marca, anio);
        this.cargaMax = cargaMax;
        this.traccion = traccion;
    }

    @Override
    void mostrarInfo() {
        super.mostrarInfo();
        System.out.println("Carga max: " + cargaMax + " kg | Traccion: " + traccion);
    }

    @Override
    String getTipo() { return "Camioneta"; }
}

public class Main {
    public static void main(String[] args) {
        Vehiculo[] vehiculos = {
            new Auto("Toyota", 2023, 4, "Gasolina"),
            new Camioneta("Ford", 2022, 1500.0, "4x4")
        };
        for (Vehiculo v : vehiculos) {
            System.out.println("Tipo: " + v.getTipo());
            v.mostrarInfo();
            System.out.println();
        }
    }
}
